ALTER TABLE "platform_schedule_runs" DROP CONSTRAINT "platform_schedule_runs_result_check";--> statement-breakpoint
ALTER TABLE "platform_schedule_runs" ADD CONSTRAINT "platform_schedule_runs_result_check" CHECK (("platform_schedule_runs"."status"='running' AND "platform_schedule_runs"."finished_at" IS NULL AND "platform_schedule_runs"."error_code" IS NULL AND "platform_schedule_runs"."result" IS NULL) OR ("platform_schedule_runs"."status"='succeeded' AND "platform_schedule_runs"."finished_at" IS NOT NULL AND "platform_schedule_runs"."error_code" IS NULL AND "platform_schedule_runs"."result" IS NOT NULL AND jsonb_typeof("platform_schedule_runs"."result")='object') OR ("platform_schedule_runs"."status" IN ('failed','rejected') AND "platform_schedule_runs"."finished_at" IS NOT NULL AND "platform_schedule_runs"."error_code" IS NOT NULL AND "platform_schedule_runs"."result" IS NULL));